#!/usr/bin/env python3
"""Generate the v1 TypeScript types and client from the live FastAPI schema.

The schema is not a checked-in copy: it is built by calling `create_app`, so the
generated package is a statement about the application this checkout actually
serves. The document written to `openapi.json` is the `/v1` half of that schema,
with the component schemas reachable from those operations and nothing else, so
a legacy route cannot slip into the versioned package merely because it exists
in the same process.

**Generated files carry a DO NOT EDIT header.** The way to change them is to
change the route and run this script. `tests/premium/T13` regenerates into a
temporary directory and compares bytes, which is what makes "reproducible" a
property a machine checks rather than a promise in a comment.

Determinism is deliberate and total: JSON is sorted and written without a
timestamp, components and operations are walked in sorted order, and no output
embeds a path, a machine name, or the time of generation. Generating twice in
the same environment produces identical bytes.
"""

from __future__ import annotations

import argparse
import json
import re
from pathlib import Path
from typing import Any

from ravel.config import Settings
from ravel.gateway.app import create_app

PACKAGE_ROOT = Path(__file__).resolve().parent

#: The configuration the schema is generated under. It names a database that
#: the generation never opens: `create_app` builds an engine lazily, and no
#: route is called. The secret is a placeholder of a valid shape and is never
#: written into the schema or the generated code.
GENERATION_SECRET = "api-client-generation-only-not-a-deployed-secret"

#: Matches a component reference, e.g. `#/components/schemas/Page_NodeView_`.
REFERENCE = re.compile(r"^#/components/schemas/(.+)$")

#: An identifier TypeScript accepts without quoting.
IDENTIFIER = re.compile(r"^[A-Za-z_$][A-Za-z0-9_$]*$")

DO_NOT_EDIT = "Generated by packages/api-client/generate.py. DO NOT EDIT."


def build_document() -> dict[str, Any]:
    """The `/v1` OpenAPI document, as the application currently declares it."""
    settings = Settings(
        env="test",
        postgres_db="ravel_api_client",
        RAVEL_POSTGRES_DSN=None,
        gateway_jwt_secret=GENERATION_SECRET,
    )
    application = create_app(settings=settings, heartbeat_seconds=None)
    return versioned_document(application.openapi())


def versioned_document(schema: dict[str, Any]) -> dict[str, Any]:
    """Keep every `/v1` operation and the components they actually reach.

    Dropping unreferenced components is not cosmetic. A generated client that
    exported the legacy `MemberView` because the process happened to serve it
    would invite a desktop screen to bind to a shape this contract never
    promised; the package should be exactly the closure of the versioned API.
    """
    paths = {
        path: operations
        for path, operations in schema.get("paths", {}).items()
        if path.startswith("/v1/")
    }
    components = schema.get("components", {})
    schemas = components.get("schemas", {})

    referenced: set[str] = set()
    pending: list[Any] = list(paths.values())
    while pending:
        node = pending.pop()
        if isinstance(node, dict):
            target = node.get("$ref")
            if isinstance(target, str):
                match = REFERENCE.match(target)
                if match and match.group(1) not in referenced:
                    name = match.group(1)
                    referenced.add(name)
                    if name in schemas:
                        pending.append(schemas[name])
            pending.extend(node.values())
        elif isinstance(node, list):
            pending.extend(node)

    kept = {name: schemas[name] for name in sorted(referenced) if name in schemas}
    document: dict[str, Any] = {
        "openapi": schema.get("openapi", "3.1.0"),
        "info": schema.get("info", {}),
        "paths": paths,
    }
    if kept:
        document["components"] = {"schemas": kept}
    security = components.get("securitySchemes")
    if security:
        document["components"]["securitySchemes"] = security
    return document


# ── TypeScript type expressions ─────────────────────────────────────────────


def type_name(component: str) -> str:
    """A TypeScript-safe name for a component schema."""
    cleaned = re.sub(r"[^A-Za-z0-9_$]", "_", component)
    if not cleaned or cleaned[0].isdigit():
        cleaned = f"_{cleaned}"
    return cleaned


def literal(value: Any) -> str:
    """A TypeScript literal for an enum or const value."""
    if isinstance(value, str):
        return json.dumps(value, ensure_ascii=False)
    if value is True:
        return "true"
    if value is False:
        return "false"
    if value is None:
        return "null"
    return str(value)


def ts_type(schema: Any, *, indent: int = 0) -> str:
    """One TypeScript type expression for an OpenAPI schema fragment.

    Every branch ends in something TypeScript accepts. `unknown` is the answer
    for a schema this generator does not understand, and it is deliberately not
    `any`: a client that has to narrow an unknown value is a client that cannot
    silently use the wrong shape.
    """
    if not isinstance(schema, dict) or not schema:
        return "unknown"

    target = schema.get("$ref")
    if isinstance(target, str):
        match = REFERENCE.match(target)
        if match:
            return type_name(match.group(1))
        return "unknown"

    for combinator in ("anyOf", "oneOf"):
        options = schema.get(combinator)
        if isinstance(options, list) and options:
            rendered = [ts_type(option, indent=indent) for option in options]
            unique = list(dict.fromkeys(rendered))
            return " | ".join(unique)

    options = schema.get("allOf")
    if isinstance(options, list) and options:
        rendered = [ts_type(option, indent=indent) for option in options]
        return " & ".join(dict.fromkeys(rendered))

    if "const" in schema:
        return literal(schema["const"])

    values = schema.get("enum")
    if isinstance(values, list) and values:
        return " | ".join(literal(value) for value in values)

    declared = schema.get("type")
    if isinstance(declared, list):
        rendered = [
            ts_type({**schema, "type": item}, indent=indent)
            for item in declared
        ]
        return " | ".join(dict.fromkeys(rendered))

    if declared == "null":
        return "null"
    if declared == "boolean":
        return "boolean"
    if declared in ("integer", "number"):
        return "number"
    if declared == "string":
        return "string"
    if declared == "array":
        items = ts_type(schema.get("items", {}), indent=indent)
        return f"Array<{items}>"
    if declared == "object" or "properties" in schema or "additionalProperties" in schema:
        properties = schema.get("properties")
        if isinstance(properties, dict) and properties:
            required = set(schema.get("required", []))
            fields = []
            for name in sorted(properties):
                optional = "" if name in required else "?"
                key = name if IDENTIFIER.match(name) else json.dumps(name)
                fields.append(
                    f"{key}{optional}: {ts_type(properties[name], indent=indent + 1)}"
                )
            return "{ " + "; ".join(fields) + " }"
        extra = schema.get("additionalProperties")
        if isinstance(extra, dict):
            return f"Record<string, {ts_type(extra, indent=indent)}>"
        if extra is False:
            return "Record<string, never>"
        return "Record<string, unknown>"
    return "unknown"


def render_types(document: dict[str, Any]) -> str:
    """`types.ts`: every reachable component, sorted by its schema name."""
    schemas = document.get("components", {}).get("schemas", {})
    lines = [f"// {DO_NOT_EDIT}", ""]
    for name in sorted(schemas):
        rendered = ts_type(schemas[name])
        lines.append(f"export type {type_name(name)} = {rendered};")
        lines.append("")
    return "\n".join(lines)


# ── The client ──────────────────────────────────────────────────────────────


def response_type(operation: dict[str, Any]) -> str:
    """The TypeScript type of a successful response."""
    responses = operation.get("responses", {})
    successful = [
        (str(code), response)
        for code, response in responses.items()
        if str(code).startswith("2")
    ]
    for _code, response in sorted(successful):
        content = response.get("content")
        if isinstance(content, dict) and content:
            json_body = content.get("application/json")
            if isinstance(json_body, dict) and isinstance(
                json_body.get("schema"), dict
            ):
                return ts_type(json_body["schema"])
            return "Blob"
    return "void"


def _parameters(operation: dict[str, Any], where: str) -> list[dict[str, Any]]:
    found = [
        parameter
        for parameter in operation.get("parameters", [])
        if parameter.get("in") == where
    ]
    return sorted(found, key=lambda parameter: str(parameter.get("name", "")))


def _options_type(
    name: str,
    operation: dict[str, Any],
    path_parameters: list[dict[str, Any]],
    query_parameters: list[dict[str, Any]],
) -> tuple[str, bool]:
    """An options object type, and whether a caller must supply it."""
    fields: list[str] = []
    required_any = False
    if path_parameters:
        required_any = True
        inner = "; ".join(
            f"{parameter['name']}: {ts_type(parameter.get('schema', {}))}"
            for parameter in path_parameters
        )
        fields.append(f"path: {{ {inner} }}")
    if query_parameters:
        inner_fields = []
        query_required = any(parameter.get("required") for parameter in query_parameters)
        if query_required:
            required_any = True
        for parameter in query_parameters:
            optional = "" if parameter.get("required") else "?"
            key = (
                parameter["name"]
                if IDENTIFIER.match(parameter["name"])
                else json.dumps(parameter["name"])
            )
            inner_fields.append(
                f"{key}{optional}: {ts_type(parameter.get('schema', {}))}"
            )
        optional = "" if query_required else "?"
        fields.append(f"query{optional}: {{ " + "; ".join(inner_fields) + " }")

    schema = (
        operation.get("requestBody", {})
        .get("content", {})
        .get("application/json", {})
        .get("schema")
    )
    if isinstance(schema, dict):
        optional = "" if operation["requestBody"].get("required") else "?"
        if not optional:
            required_any = True
        fields.append(f"body{optional}: {ts_type(schema)}")

    fields.append("signal?: AbortSignal")
    return f"export type {name} = {{ " + "; ".join(fields) + " };", required_any


def _path_expression(path: str, path_parameters: list[dict[str, Any]]) -> str:
    names = {parameter["name"] for parameter in path_parameters}
    rendered = path
    for name in names:
        rendered = rendered.replace(
            "{" + name + "}", "${encodeURIComponent(options.path." + name + ")}"
        )
    if names:
        return f"`{rendered}`"
    return json.dumps(path)


def render_client(document: dict[str, Any]) -> str:
    """`client.ts`: one typed method per `/v1` operation, plus the stream."""
    operations: list[tuple[str, str, dict[str, Any]]] = []
    for path in sorted(document.get("paths", {})):
        for method, operation in sorted(document["paths"][path].items()):
            if isinstance(operation, dict):
                operations.append((path, method.upper(), operation))

    used: set[str] = set()
    methods: list[str] = []
    option_types: list[str] = []
    for path, method, operation in operations:
        base_name = str(operation.get("operationId") or f"{method}_{path}")
        name = re.sub(r"[^A-Za-z0-9_$]", "_", base_name)
        if not name or name[0].isdigit():
            name = f"_{name}"
        candidate = name
        suffix = 2
        while candidate in used:
            candidate = f"{name}_{suffix}"
            suffix += 1
        used.add(candidate)

        path_parameters = _parameters(operation, "path")
        query_parameters = _parameters(operation, "query")
        options_name = f"{candidate[0].upper()}{candidate[1:]}Options"
        options_type, required = _options_type(
            options_name, operation, path_parameters, query_parameters
        )
        option_types.append(options_type)
        result = response_type(operation)
        expression = _path_expression(path, path_parameters)
        default = "" if required else " = {}"
        body_lines = []
        if query_parameters:
            # Under `exactOptionalPropertyTypes`, an omitted optional argument
            # and one explicitly set to `undefined` are different things. The
            # caller omitted it, so the request must omit the property rather
            # than pass `undefined` through a type that does not admit it.
            body_lines.append(
                "      ...(options.query !== undefined"
                " ? { query: options.query } : {}),"
            )
        if isinstance(
            operation.get("requestBody", {})
            .get("content", {})
            .get("application/json", {})
            .get("schema"),
            dict,
        ):
            body_lines.append(
                "      ...(options.body !== undefined"
                " ? { body: options.body } : {}),"
            )
        body_lines.append(
            "      ...(options.signal !== undefined"
            " ? { signal: options.signal } : {}),"
        )
        methods.append(
            "\n".join(
                [
                    f"  async {candidate}(",
                    f"    options: {options_name}{default},",
                    f"  ): Promise<{result}> {{",
                    f"    return this.call<{result}>({json.dumps(method)}, {expression}, {{",
                    *body_lines,
                    "    });",
                    "  }",
                ]
            )
        )

    method_text = "\n\n".join(methods)
    option_text = "\n".join(option_types)
    imported = ", ".join(
        type_name(name)
        for name in sorted(
            document.get("components", {}).get("schemas", {})
        )
    )
    import_line = (
        f'import type {{ {imported} }} from "./types";' if imported else ""
    )
    return f"""// {DO_NOT_EDIT}

{import_line}

export interface ClientOptions {{
  readonly baseUrl: string;
  /** A bearer token, or a function that returns the current one. */
  readonly token: string | (() => string | Promise<string>);
  /** Injected for a test or a non-browser transport; defaults to global fetch. */
  readonly fetch?: typeof fetch;
}}

export interface RequestOptions {{
  readonly query?: Record<string, unknown>;
  readonly body?: unknown;
  readonly signal?: AbortSignal;
}}

/** The v1 error envelope, carried as an exception. */
export class ApiError extends Error {{
  constructor(
    readonly status: number,
    readonly code: string,
    readonly requestId: string,
    readonly details: Record<string, unknown>,
    message: string,
  ) {{
    super(message);
    this.name = "ApiError";
  }}

  static async fromResponse(response: Response): Promise<ApiError> {{
    let envelope: Record<string, unknown> = {{}};
    try {{
      const parsed: unknown = await response.json();
      if (parsed !== null && typeof parsed === "object") {{
        envelope = parsed as Record<string, unknown>;
      }}
    }} catch {{
      // A refusal from something other than the Gateway is still a refusal;
      // it simply has no envelope, and the status is all there is to report.
    }}
    const code =
      typeof envelope.code === "string" ? envelope.code : `HTTP_${{response.status}}`;
    const requestId =
      typeof envelope.request_id === "string" ? envelope.request_id : "";
    const details =
      envelope.details !== null && typeof envelope.details === "object"
        ? (envelope.details as Record<string, unknown>)
        : {{}};
    const message =
      typeof envelope.message === "string"
        ? envelope.message
        : `HTTP ${{response.status}}`;
    return new ApiError(response.status, code, requestId, details, message);
  }}
}}

function queryString(query: Record<string, unknown> | undefined): string {{
  if (!query) return "";
  const search = new URLSearchParams();
  for (const [key, value] of Object.entries(query)) {{
    if (value === undefined || value === null) continue;
    if (Array.isArray(value)) {{
      for (const item of value) search.append(key, String(item));
    }} else {{
      search.set(key, String(value));
    }}
  }}
  const rendered = search.toString();
  return rendered ? `?${{rendered}}` : "";
}}

/** The generated client. Every method is one operation of the v1 contract. */
export class V1Client {{
  private readonly fetcher: typeof fetch;

  constructor(private readonly options: ClientOptions) {{
    this.fetcher = options.fetch ?? globalThis.fetch.bind(globalThis);
  }}

  private async authorization(): Promise<string> {{
    const token =
      typeof this.options.token === "function"
        ? await this.options.token()
        : this.options.token;
    return `Bearer ${{token}}`;
  }}

  private async call<T>(
    method: string,
    path: string,
    options: RequestOptions,
  ): Promise<T> {{
    const headers: Record<string, string> = {{
      Authorization: await this.authorization(),
      Accept: "application/json",
    }};
    if (options.body !== undefined) headers["Content-Type"] = "application/json";
    const init: RequestInit = {{ method, headers }};
    if (options.signal !== undefined) init.signal = options.signal;
    if (options.body !== undefined) {{
      init.body = JSON.stringify(options.body);
    }}
    const response = await this.fetcher(
      `${{this.options.baseUrl.replace(/\\/$/, "")}}${{path}}${{queryString(options.query)}}`,
      init,
    );
    if (!response.ok) throw await ApiError.fromResponse(response);
    if (response.status === 204) return undefined as T;
    const media = response.headers.get("content-type") ?? "";
    if (media.includes("application/json")) return (await response.json()) as T;
    return (await response.blob()) as T;
  }}

{method_text}
}}

{option_text}

/** One event on the project stream, in the wire shape the Gateway sends. */
export interface ProjectEventWire {{
  event_id: string;
  project_id: string;
  seq: number;
  event_type: string;
  actor_type: string;
  actor_id: string;
  payload: Record<string, unknown>;
  created_at: string;
}}

export interface AnchorFrame {{
  type: "anchor";
  project_id: string;
  display_id: string;
  status: string;
  head_seq: number;
}}

export interface EventFrame extends ProjectEventWire {{
  type: "event";
}}

export interface HeartbeatFrame {{
  type: "heartbeat";
  head_seq: number;
}}

export interface ResyncFrame {{
  type: "resync_required";
  code: "RESYNC_REQUIRED";
  project_id: string;
  requested_after_seq: number;
  head_seq: number;
  anchor_seq: number;
  snapshot: Record<string, unknown>;
}}

export type EventStreamFrame =
  | AnchorFrame
  | EventFrame
  | HeartbeatFrame
  | ResyncFrame;

/**
 * A transport that can set an Authorization header on a WebSocket handshake.
 *
 * A browser `WebSocket` cannot; the desktop shell connects through a transport
 * that can, which is also what keeps the token out of the URL. The generated
 * package deliberately does not assume one.
 */
export interface SocketTransport {{
  (url: string, headers: Record<string, string>): WebSocketLike;
}}

/** The slice of the WebSocket API the stream helper uses. */
export interface WebSocketLike {{
  close(code?: number, reason?: string): void;
  addEventListener(type: "message", listener: (event: {{ data: unknown }}) => void): void;
}}

/**
 * Open `/v1/projects/{{project_id}}/events`, with the token in the header.
 *
 * A reconnect passes the last sequence it processed as `afterSeq`; the server
 * replays from there, or answers with a `RESYNC_REQUIRED` frame carrying a new
 * snapshot when the cursor is outside the window it promises.
 */
export function openProjectEvents(options: {{
  baseUrl: string;
  projectId: string;
  token: string;
  afterSeq?: number;
  transport: SocketTransport;
}}): WebSocketLike {{
  const base = new URL(options.baseUrl);
  base.protocol = base.protocol === "https:" ? "wss:" : "ws:";
  const url = new URL(
    `${{base.pathname.replace(/\\/$/, "")}}/v1/projects/${{encodeURIComponent(options.projectId)}}/events`,
    base,
  );
  if (options.afterSeq !== undefined) {{
    url.searchParams.set("after_seq", String(options.afterSeq));
  }}
  return options.transport(url.toString(), {{
    Authorization: `Bearer ${{options.token}}`,
  }});
}}
"""


def render_index() -> str:
    """`index.ts`: the package's whole surface."""
    return f"""// {DO_NOT_EDIT}

export * from "./types";
export * from "./client";
"""


def canonical_json(value: Any) -> str:
    """The one serialization every generated JSON file uses."""
    return json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def generate(output: Path) -> list[Path]:
    """Write every generated file under `output`, and return what was written."""
    document = build_document()
    output.mkdir(parents=True, exist_ok=True)
    source = output / "src"
    source.mkdir(parents=True, exist_ok=True)
    written: list[Path] = []
    for path, content in (
        (output / "openapi.json", canonical_json(document)),
        (source / "types.ts", render_types(document)),
        (source / "client.ts", render_client(document)),
        (source / "index.ts", render_index()),
    ):
        path.write_text(content, encoding="utf-8", newline="\n")
        written.append(path)
    return written


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--output",
        type=Path,
        default=PACKAGE_ROOT,
        help="Directory to write openapi.json and src/ into.",
    )
    arguments = parser.parse_args(argv)
    for path in generate(arguments.output):
        print(path)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
